test('invoiceTotals with decimal discount percent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 12.5 }],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  // subtotal = 95000
  // discount = 95000 * 12.5 / 100 = 11875
  // lineAmount = 95000 - 11875 = 83125
